const EMPTY = '—';

// "dropped_literature" -> "Dropped Literature"
export function formatResponseLabel(response: string): string {
  return response
    .split('_')
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ');
}

// Times in this app render as 24-hour UTC. Backend summaries are built in UTC
// (server-side `strftime("%H:%M")` of a UTC `ended_at`), so the frontend matches
// that timezone to keep popup headers and summary text aligned. Locale is fixed
// to `en-GB` because it formats 24-hour cleanly without an AM/PM suffix.
const interactionTimeFormatter = new Intl.DateTimeFormat('en-GB', {
  month: 'numeric',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
  timeZone: 'UTC',
});

// "2026-05-02T15:55:32Z" -> "02/05, 15:55" (UTC, 24h). Returns the empty placeholder
// when input is nullish or unparseable so the UI never renders the raw ISO/Invalid Date.
export function formatInteractionTime(iso: string | null | undefined): string {
  if (!iso) return EMPTY;
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? EMPTY : interactionTimeFormatter.format(d);
}

export const timeOfDayFormatter = new Intl.DateTimeFormat('en-GB', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
  timeZone: 'UTC',
});

// "2026-05-02T15:55:32Z" -> "15:55" (UTC, 24h). Short time only, no date or seconds.
export function formatTimeOfDay(iso: string | null | undefined): string {
  if (!iso) return EMPTY;
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? EMPTY : timeOfDayFormatter.format(d);
}

// 75 -> "1m 15s", 3725 -> "1h 2m". Non-finite / negative → empty placeholder so we never
// render "NaNm NaNs" when upstream stats produced a NaN duration.
export function formatSecondsHuman(seconds: number | null | undefined): string {
  if (seconds === null || seconds === undefined) return EMPTY;
  if (!Number.isFinite(seconds) || seconds < 0) return EMPTY;
  if (seconds < 60) return `${Math.round(seconds)} s`;
  const m = Math.floor(seconds / 60);
  const s = Math.round(seconds - m * 60);
  if (m < 60) return s ? `${m}m ${s}s` : `${m}m`;
  const h = Math.floor(m / 60);
  const remM = m - h * 60;
  return remM ? `${h}h ${remM}m` : `${h}h`;
}

export function canvasserName(first?: string | null, last?: string | null): string {
  return [first, last]
    .map((part) => part?.trim())
    .filter((part): part is string => !!part)
    .join(' ');
}
